import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Favicon oluşturmak teknik gibi duyulur ama doğru araçla yalnızca birkaç dakika sürer. Bir logo yüklersin, birkaç seçeneği ayarlarsın, bir dosya paketi indirirsin ve web sitene kısa bir parça eklersin. Bu kılavuz her adımı sırayla anlatır.</p>\n<p>Başlamadan önce yalnızca iki şeye ihtiyacın var: bir logo dosyası ve web sitenin dosyalarına erişim. PNG ya da SVG biçiminde kare bir logo en iyi çalışır ve sahip olduğun en büyük sürüm en keskin sonucu verir. Yalnızca bir JPG'n varsa o da işe yarar.</p>\n<p><a href=\"/tr/favicon-olusturucu\">Favicon oluşturucu</a> tüm işi tarayıcında yapar. Logon cihazından asla çıkmaz, hesap oluşturmak gerekmez ve bitmiş paket ZIP olarak indirilir. Aşağıdaki adımları izle; siten tam bir simge setine sahip olur.</p>\n<h2 id=\"step-1-prepare-your-logo\">Adım 1: logonu hazırla</h2>\n<p>Logo dosyanı aç ve kare ya da kareye yakın olduğunu doğrula. Kare bir tuval favicon'un minik alanını en iyi kullanırken, geniş ve dikdörtgen bir logo markanın üstünde ve altında boş bantlar bırakır. Logon genişse kare bir ayrıntı kırp ya da tek harfli bir sürüm kullan.</p>\n<p>Çözünürlüğü incele. 512'ye 512 piksel ya da daha büyük bir kaynak görüntü tüm favicon boyutlarına sorunsuz küçülür. Android için 512'ye gerilmiş 64 piksellik bir görüntü yumuşak görünür; bu yüzden her zaman sahip olduğun en büyük dosyayı kullan. SVG dosyası idealdir, çünkü sabit bir çözünürlüğü yoktur.</p>\n<p>Küçük metni ya da ince ayrıntıları varsa tasarımı basitleştir. Logonun altındaki bir slogan 16 pikselde ayakta kalmaz; bu yüzden favicon sürümü için onu kaldır. En güçlü öğeyle kal: sembol, baş harf ya da en belirgin biçim.</p>\n<p>Logonun şeffaf bir arka planı varsa şimdilik öyle bırak. Şeffaflık sana oluşturucuda daha fazla seçenek verir, çünkü önizlemeler ihtiyaç duyduğunu gösterirse sonra arka plan rengi ekleyebilirsin. JPG'nin şeffaflığı yoktur; bu yüzden PNG ya da SVG daha iyi bir başlangıç noktasıdır.</p>\n<h2 id=\"step-2-upload-to-the-generator\">Adım 2: logoyu oluşturucuya yükle</h2>\n<p>Favicon oluşturucuyu aç ve logonu yükleme alanına sürükle ya da dosyayı cihazından seçmek için tıkla. Logo başka bir uygulamada açıksa Ctrl ve V ile panodan kopyalanmış bir görüntüyü de yapıştırabilirsin.</p>\n<p>Araç 20 MB'a kadar PNG, SVG, JPG, WebP ve HEIC dosyalarını kabul eder. Çoğu logo bu sınırdan çok daha küçüktür; bu yüzden boyut nadiren sorun olur. Dosyan HEIC biçiminde bir telefon fotoğrafıysa fazladan adım olmadan yüklenir ve dönüştürülür.</p>\n<p>Dosya yüklenir yüklenmez oluşturucu simge paketinin önizlemesini kurar. Markayı birkaç boyutta çizilmiş görürsün; bu yüzden küçük ve büyük nasıl okunduğunu değerlendirebilirsin. Logo 16 pikselde kötü görünüyorsa kaynak görüntüyü şimdi düzelt, sonra değil.</p>\n<p>Dikdörtgen bir logo yüklediysen araç onu germeden kare tuvalin içine sığdırır. Sonucun çok küçük görünüp görünmediğini incele. Öyleyse geri dön ve devam etmeden önce markanın daha kare bir sürümünü hazırla.</p>\n<h2 id=\"step-3-set-padding-and-shape\">Adım 3: dolguyu ve biçimi ayarla</h2>\n<p>Dolgu, logon ile simgenin kenarı arasındaki boşluktur. Markanın tuvalin kenarına dokunmaması için yeterli küçük bir miktarla başla. Kenara yapışmış bir logo sıkışık görünür; özellikle her pikselin önemli olduğu sekme boyutunda.</p>\n<p>Logonun ince kenarları ya da ince çizgileri varsa dolguyu artır. İnce ayrıntılar havaya ihtiyaç duyar, yoksa küçük boyutlarda kenarla birleşir. Marka güçlü ve sade ise azalt, çünkü güçlü bir biçim sorunsuz daha fazla tuval kaplayabilir.</p>\n<p>Köşe yarıçapı simge arka planının köşelerini yuvarlar. Hafif bir yuvarlama markanın karakterini değiştirmeden görünümü yumuşatır. Tam bir yuvarlama simgeyi daireye dönüştürür; bu avatarlar ve uygulama tarzı simgelerle iyi gider ama kare bir logoyu rahatsız edici biçimde kırpabilir.</p>\n<p>Bu kontrolleri ayarlarken önizlemelere bak. Değişiklikler paketteki tüm boyutlara aynı anda uygulanır; bu yüzden tek bir ayarlama sekme simgesini, Apple simgesini ve Android simgelerini birlikte günceller. En küçük önizleme hâlâ net okunduğunda dur.</p>\n<h2 id=\"step-4-choose-a-background-fill\">Adım 4: arka plan rengi seç</h2>\n<p>Arka plan rengi şeffaf bir logonun arkasında ne olduğudur. Onu şeffaf bırakmak simgeyi hafif tutar ve tarayıcı sekmesinin rengini gösterir. Bu açık sekmelerdeki koyu ve belirgin logolar için iyi çalışır.</p>\n<p>Logo soluk, ince ya da açık renkli olduğunda katı bir dolgu ekle. Tasarımın arkasındaki beyaz ya da marka renginde bir kare her sekmede kontrast verir. Markanla uyuşan bir dolgu seç, çünkü o renk simgenin kimliğinin parçası olur.</p>\n<p>Apple Touch simgeleri şeffaflığı yok sayar ve boş bölgeleri siyahla doldurur; bu yüzden ana ekran simgesi için katı bir dolgu güvenli seçimdir. Sekme favicon'un şeffaf kalır ama Apple simgesinin dolguya ihtiyacı varsa oluşturucu ikisini de aynı ayarla işler.</p>\n<p>Dolguyu açık ve koyu sekme önizlemelerinde incele. Açık bir sekmede çok iyi görünen bir dolgu koyu bir sekmede ağır görünebilir ve tersi de olur. Doğru dolgu markayı iki temada da boğmadan görünür tutar.</p>\n<h2 id=\"step-5-check-the-previews\">Adım 5: önizlemeleri incele</h2>\n<p>Oluşturucu simgeni tarayıcının açık ve koyu sekmelerinde gösterir. Logon koyuysa önce koyu görünüme, açıksa açık görünüme bak. Logonun renginin sekme rengiyle uyuştuğu önizleme, sorunların ortaya çıktığı yerdir.</p>\n<p>Özellikle en küçük önizlemeye, 16 piksellik sekme simgesine dikkat et. Ziyaretçilerin en sık gördüğü boyuttur ve ayrıntının öldüğü yerdir. Orada hâlâ markayı tanıyabiliyorsan favicon işe yarar. Lekeye dönüşüyorsa kaynak görüntüyü basitleştir ya da dolguyu artır.</p>\n<p>En büyük önizlemeye, 512 piksellik Android simgesine de bak. Küçükte iyi okunan bir marka büyükte boş ya da kaybolmuş görünebilir; özellikle ince tek harfse. Büyük görünüm tasarımın ana ekranda ayakta kalıp kalmadığını gösterir.</p>\n<p>Bu adımı atlama. Önizleme en yaygın iki arızayı yakalar: koyu modda kaybolan bir simge ve sekme boyutunda lapa olan bir marka. Bunları şimdi düzeltmek saniyeler sürerken, her şeyi yükledikten sonra düzeltmek tam bir önbellek temizleme turu alır.</p>\n<h2 id=\"step-6-download-the-pack\">Adım 6: paketi indir</h2>\n<p>Önizlemeler iyi göründüğünde ZIP'i indir. İçinde favicon.ico, Apple Touch Icon, 192 ve 512 piksellik Android simgeleri, site.webmanifest dosyası ve HTML parçası bulursun. Her şey adlandırılmış ve yüklemeye hazır gelir.</p>\n<p>Yalnızca birine ihtiyacın varsa tek dosyaları da indirebilirsin. Yalnızca favicon.ico almak eski bir sitede hızlı bir düzeltme için yeterken, tam ZIP yeni bir sitenin tüm sete ihtiyacı olduğunda doğrudur.</p>\n<p>Paketi bilgisayarında aç ve yüklemeden önce dosyalara bak. Simge boyutlarının bulunduğunu ve manifesto dosyasının dahil olduğunu doğrula. Şimdi hızlı bir bakış, siteni düzenledikten sonra eksik dosya sürprizini önler.</p>\n<p>ZIP'in bir kopyasını güvenli bir yerde sakla. Marka değiştirirsen ya da sonra site dosyalarını kaybedersen ZIP, simge setini geri yüklemenin en hızlı yoludur. Ayrıca sıfırdan başlamak yerine bir ayarla paketi yeniden oluşturmaya yarar.</p>\n<h2 id=\"step-7-upload-the-files\">Adım 7: dosyaları yükle</h2>\n<p>Simge dosyalarını web sitenin kök klasörüne, ana sayfanın bulunduğu klasöre yükle. Tarayıcılar varsayılan olarak kökte favicon.ico arar; bu yüzden onu oraya koymak parçayı içermeyen sayfaları kapsar.</p>\n<p>Dosyaları kopyalamak için barındırma hizmetinin dosya yöneticisini, FTP istemcisini ya da dağıtım aracını kullan. Dosyalar küçüktür; bu yüzden yükleme saniyeler sürer. Her dosyanın kökte kaldığını ve yanlışlıkla bir alt klasörün içinde olmadığını doğrula.</p>\n<p>Site oluşturucun kök klasörü göstermiyorsa panelinde favicon ya da site simgesi seçeneği ara. Birçok oluşturucu yüklenen bir simgeyi kabul eder ve dosyaları yerleştirmeyi kendisi üstlenir. Bu durumda 512 piksellik PNG'yi yükle, çünkü oluşturucular genellikle büyük bir görüntüden yeniden boyutlandırır.</p>\n<p>HTML parçasını da güncellemedikçe dosyaların adını değiştirme. Parçada eski yolu olan yeniden adlandırılmış bir dosya, eksik bir dosyayla aynıdır ve tarayıcı varsayılan simgeyi gösterir.</p>\n<h2 id=\"step-8-add-the-html-snippet\">Adım 8: HTML parçasını ekle</h2>\n<p>Paketle gelen HTML parçasını aç. Favicon, Apple Touch Icon ve web manifestosu için bağlantı etiketleri içerir. Tüm bloğu yolları düzenlemeden geldiği gibi kopyala.</p>\n<p>Parçayı sayfalarının head bölümüne, diğer meta ve bağlantı etiketlerinin yanına yapıştır. Sade HTML sitesinde her sayfaya ya da paylaşılan bir başlık şablonuna ekle. React ya da Next.js'te tüm sayfaların paylaştığı tasarım ya da belge dosyasına bir kez ekle.</p>\n<p>Dosyayı kaydet ve siteni tarayıcıda yeniden yükle. Sekme simgesi yeni favicon'una değişmelidir. Değişmezse eski simge önbellekte olabilir; bu normaldir ve sonraki adımda ele alınır.</p>\n<p>Önbelleği temizledikten sonra simge hâlâ görünmüyorsa parçanın yollarını incele. Var olmayan bir alt klasöre işaret eden bir yol olağan nedendir. Parça dosyaların sitenin kökünde olduğunu varsayar; bu yüzden başka bir konum güncellenmiş yollar ister.</p>\n<h2 id=\"step-9-clear-the-cache-and-test\">Adım 9: önbelleği temizle ve dene</h2>\n<p>Tarayıcılar faviconları uzun süre önbelleğe alır; bu yüzden kendi tarayıcın yüklemeden sonra eski simgeyi göstermeye devam edebilir. Ctrl, Shift ve R ile zorla yenile ya da favicon URL'sini doğrudan aç ve yeni bir indirmeyi zorlamak için o sayfayı yenile.</p>\n<p>Simgeyi ikinci bir tarayıcıda ya da önbelleğin boş olduğu gizli bir pencerede dene. Gizli bir pencere yeni bir ziyaretçinin gördüğünü gösterir; bu dürüst bir denemedir. Simge orada görünüyorsa yükleme işe yaramıştır ve yalnızca ana tarayıcının önbelleği eskidir.</p>\n<p>Siteyi telefonunun ana ekranına ekle ve Apple ya da Android simgesini incele. Ana ekran simgesi en büyük sürümdür; bu yüzden sekme önizlemesinin gizlediği arızaları gösterir. Telefonda iyi görünüyorsa paket tamamdır.</p>\n<p>Sayfayı yer imlerine kaydet ve listeye bak. Favicon kaydedilen başlığın yanında görünmelidir. Yer imlerinde eksik bir simge genellikle parçanın yolunun yanlış olduğu ya da dosyanın yüklenmediği anlamına gelir.</p>\n<h2 id=\"step-10-when-to-regenerate\">Adım 10: ne zaman yeniden oluşturmalı?</h2>\n<p>Logon her değiştiğinde paketi yeniden oluştur; değişim küçük olsa bile. Yeni bir logo, yeni bir marka rengi ya da inceltilmiş bir sembol yeni bir paket hak eder, çünkü eski bir favicon yeni markayı göründüğü her yerde sessizce çelişkiye düşürür.</p>\n<p>Tek bir dosya yerine tüm paketi yeniden oluştur. Yalnızca favicon.ico'yu değiştirmek eski markayı ana ekranlarda ve manifestoda bırakır; bu cihazlarda eski ve yeni simgelerin kafa karıştırıcı bir karışımını oluşturur.</p>\n<p>Sitenin adını ya da tema rengini değiştirirsen manifestoyu da güncelle. Oluşturucu her paketle yeni bir manifesto yazar; bu yüzden yeniden oluşturmak adı, renkleri ve simgeleri JSON'u elle düzenlemeden senkron tutar.</p>\n<p>Yeni paketin yayında olduğunu doğrulayana kadar eski ZIP'i sakla. Yeni yüklemede sorun çıkarsa eski dosyalar önceki simgeyi saniyeler içinde geri yükler. Yeni simge sekmede, telefonda ve yer imlerinde doğrulandıktan sonra eski paket gidebilir.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: favicon oluşturma denetim listesi</h2>\n<p>En az 512 piksellik PNG ya da SVG biçiminde kare bir logo hazırla; küçük metin olmadan. Oluşturucuya yükle, dolguyu ve köşe yarıçapını ayarla, arka plan rengi seç ve en küçük boyutta açık ve koyu önizlemeleri incele.</p>\n<p>ZIP'i indir, dosyaları sitenin köküne yükle, parçayı paylaşılan head şablonuna yapıştır ve gizli bir pencerede ve telefonunda dene. Eski simge görünmeye devam ederse önbelleği temizle.</p>\n<p>Paketteki her dosyayı derinlemesine öğrenmek için <a href=\"/tr/blog/favicon-olusturucu-rehberi\">Favicon Oluşturucu Tam Kılavuzu</a> yazısını oku ve boyut boyut döküm için <a href=\"/tr/blog/favicon-boyutlari-aciklandi\">Favicon Boyutları Açıklaması: 16×16'dan 512×512'ye</a> yazısını oku. Şimdi <a href=\"/tr/favicon-olusturucu\">favicon oluşturucu</a> ile başla.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Favicon oluşturmak için hangi logo dosyasını kullanmalıyım?","answer":"En az 512 piksellik PNG ya da SVG biçiminde kare bir logo en iyi çalışır. SVG idealdir, çünkü her boyuta netliğini kaybetmeden ölçeklenir. JPG de işe yarar ama şeffaflığı yoktur; bu yüzden PNG ya da SVG arka plan üzerinde daha fazla kontrol verir."},{"question":"Yeni favicon'um neden hemen görünmüyor?","answer":"Tarayıcılar faviconları çok agresif önbelleğe alır; bazen haftalarca. Zorla yenile, favicon URL'sini doğrudan aç ve yenile ya da gizli bir pencerede dene. Yeni simge diğer ziyaretçilere önbellekleri dolduğunda görünür ya da simge bağlantılarına sürüm numarası eklersen hemen görünür."},{"question":"Favicon dosyalarını web sitemde nereye koyarım?","answer":"Web sitenin kök klasörüne yükle; ana sayfanın bulunduğu klasöre. Tarayıcılar varsayılan olarak kökte favicon.ico arar. Sonra tarayıcının Apple simgesini ve manifestoyu da bulması için HTML parçasını sayfalarının head bölümüne yapıştır."},{"question":"HTML parçasını her sayfaya eklemem gerekir mi?","answer":"Tüm sayfaların kullandığı paylaşılan head şablonuna ya da tasarım dosyasına bir kez ekle. Sade HTML sitesinde bu paylaşılan başlık demektir; React ya da Next.js'te tasarım ya da belge dosyası demektir. Her sayfaya elle yapıştırman gerekmez."},{"question":"Telefonumdaki bir fotoğraftan favicon oluşturabilir miyim?","answer":"Evet, oluşturucu iPhone HEIC fotoğraflarını, JPG ve PNG dosyalarının yanı sıra kabul eder. Bir fotoğraf 16 pikselde nadiren iyi bir favicon verir; bu yüzden en iyi sonuç için önce belirgin bir ayrıntıyı ya da tek bir güçlü biçimi kırp."},{"question":"Logom kare değilse ne olur?","answer":"Oluşturucu dikdörtgen bir logoyu germeden kare tuvalin içine sığdırır ama sonuç küçük görünebilir ve yanlarda boş alan olabilir. En iyi sonuç için markanın kare bir sürümünü hazırla ya da yüklemeden önce en tanınabilir ayrıntıyı kırp."}];
